/// Compile-time configuration generated by build.rs from profile
#[allow(dead_code)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/generated_config.rs"));
}

/// Configuration for the admin web application
#[derive(Debug, Clone)]
pub struct AdminConfig {
    /// SpacetimeDB server URI
    pub spacetimedb_uri: String,
    /// SpacetimeDB module name
    pub spacetimedb_module_name: String,
    /// OAuth configuration
    pub oauth: OAuthConfig,
}

/// OAuth/OIDC configuration
#[derive(Debug, Clone)]
pub struct OAuthConfig {
    /// OIDC issuer URL (discovery endpoint base)
    pub issuer_url: String,
    /// OAuth client ID
    pub client_id: String,
    /// OAuth redirect URI
    pub redirect_uri: String,
    /// OAuth scopes (space-separated)
    pub scope: String,
}

impl Default for AdminConfig {
    fn default() -> Self {
        Self {
            spacetimedb_uri: generated::GENERATED_SPACETIMEDB.uri.to_string(),
            spacetimedb_module_name: generated::GENERATED_SPACETIMEDB.module_name.to_string(),
            oauth: OAuthConfig::default(),
        }
    }
}

impl Default for OAuthConfig {
    fn default() -> Self {
        Self {
            issuer_url: generated::GENERATED_OAUTH.issuer_url.to_string(),
            client_id: generated::GENERATED_OAUTH.client_id.to_string(),
            redirect_uri: generated::GENERATED_OAUTH.redirect_uri.to_string(),
            scope: generated::GENERATED_OAUTH.scope.to_string(),
        }
    }
}

impl AdminConfig {
    /// Load configuration from compile-time generated configuration profile
    pub fn from_profile() -> Self {
        Self {
            spacetimedb_uri: generated::GENERATED_SPACETIMEDB.uri.to_string(),
            spacetimedb_module_name: generated::GENERATED_SPACETIMEDB.module_name.to_string(),
            oauth: OAuthConfig {
                issuer_url: generated::GENERATED_OAUTH.issuer_url.to_string(),
                client_id: generated::GENERATED_OAUTH.client_id.to_string(),
                redirect_uri: generated::GENERATED_OAUTH.redirect_uri.to_string(),
                scope: generated::GENERATED_OAUTH.scope.to_string(),
            },
        }
    }

    /// Load configuration
    pub fn load() -> Self {
        Self::from_profile()
    }
}
